head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.trigger1_onclick = function(e) {
    var options = {
        id: "pop1",
        type: "window",
        width: 500,
        minimumWidth: 100,
        height: 500,
        top: 50,
        left: 50,
        popupName: "test",
        modal: true,
        useIFrame: true,
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: scroll,
        title: 'test222',
        useControl: true,
        controls: {
            minimize: true,
            maximize: true,
            close: true
        },
        foldSize: {
            width: 500
        },
        foldOnMinimized: false
    };
    $w.openPopup("windowcontainer_foldOnMinimized_WPF-1985_(WSQ-3234)_sub.xml", options);
};
scwin.checkElement = function(id) {
    if (scwin.__getDom(id)) {
        return true;
    }
    return false
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 22-Feb-2018
}
